+
+bool PolicyAgent::hasScreenInhibition() const
+{
+    return std::ranges::any_of(m_typesToCookie.value(ChangeScreenSettings), [this](uint cookie) {
+        return !m_minimizedScreenInhibitions.contains(cookie);
+    });
+}
+
+QSet<uint> PolicyAgent::minimizedScreenInhibitions() const
+{
+    QSet<uint> minimized;
+    if (!m_windowTasksModel) {
+        return minimized;
+    }
+
+    for (uint cookie : m_typesToCookie.value(ChangeScreenSettings)) {
+        const QString who = m_cookieToInhibition.value(cookie).who;
+        bool hasWindow = false;
+        bool allMinimized = true;
+        for (int row = 0; row < m_windowTasksModel->rowCount(); ++row) {
+            const QModelIndex index = m_windowTasksModel->index(row, 0);
+            if (index.data(TaskManager::AbstractTasksModel::AppId).toString().compare(who, Qt::CaseInsensitive) != 0
+                && index.data(TaskManager::AbstractTasksModel::AppName).toString().compare(who, Qt::CaseInsensitive) != 0) {
+                continue;
+            }
+            hasWindow = true;
+            if (!index.data(TaskManager::AbstractTasksModel::IsMinimized).toBool()) {
+                allMinimized = false;
+                break;
+            }
+        }
+        // Inhibitions that don't belong to a window (e.g. a file transfer) always keep the screen on
+        if (hasWindow && allMinimized) {
+            minimized.insert(cookie);
+        }
+    }
+    return minimized;
+}
+
+void PolicyAgent::updateMinimizedScreenInhibitions(RequiredPolicies oldPolicies)
+{
+    const QSet<uint> minimized = minimizedScreenInhibitions();
+    if (minimized != m_minimizedScreenInhibitions) {
+        qCDebug(POWERDEVIL) << "Screen inhibitions of apps with only minimized windows:" << minimized;
+        m_minimizedScreenInhibitions = minimized;
+        // Let the screen locker check HasInhibition again
+        Q_EMIT InhibitionsChanged({}, {});
+    }
+
+    const RequiredPolicies newPolicies = unavailablePolicies();
+    if (oldPolicies != newPolicies) {
         // emit the signal - inhibition has changed
-        Q_EMIT unavailablePoliciesChanged(unavailablePolicies());
+        Q_EMIT unavailablePoliciesChanged(newPolicies);
     }
 }

